/** The raw target inputs the drawer collects (all optional strings). */
export interface TargetFormValues {
  target_table?: string;
  target_schema?: string;
  target_catalog?: string;
  target_namespace?: string;
  target_path?: string;
  target_format?: 'csv' | 'parquet';
  /**
   * Flat-file target mode (#1180): `single` is a literal `target_path`; `batch` selects a file at
   * run time via `target_prefix`/`target_pattern`/ `target_strategy`(/`target_batch`).
   */
  target_mode?: 'single' | 'batch';
  target_prefix?: string;
  target_pattern?: string;
  target_strategy?: 'latest' | 'specific';
  target_batch?: string;
  /** Scale-aware execution (#595). Off by default: sampling changes what a
   *  verdict *means*, so it is opt-in per suite and never inherited. */
  sampling_enabled?: boolean;
  sampling_strategy?: SampleStrategy;
  sampling_rows?: number | null;
  /** `random` only — the backend 422s a seed on `head`, since a head sample
   *  always reads the first rows in storage order and cannot be seeded. */
  sampling_seed?: number | null;
}

/** Narrow an untyped value to one of a closed set, else `undefined`. */
function asOneOf<T extends string>(value: unknown, allowed: readonly T[]): T | undefined {
  return allowed.includes(value as T) ? (value as T) : undefined;
}

/** The stored `sampling` block, narrowed field by field for prefill. */
export function targetSampling(
  target: Record<string, unknown> | null | undefined,
): { strategy?: SampleStrategy; rows?: number; seed?: number } | undefined {
  const raw = target?.sampling;
  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) return undefined;
  const bag = raw as Record<string, unknown>;
  return {
    strategy: asOneOf(bag.strategy, SAMPLE_STRATEGIES),
    rows: typeof bag.rows === 'number' ? bag.rows : undefined,
    seed: typeof bag.seed === 'number' ? bag.seed : undefined,
  };
}

/**
 * Narrow an untyped stored `file_format` to the supported set, else `undefined` — the suite target
 * is an untyped JSONB bag, so a stray value (e.g.
 */
export function asFileFormat(value: unknown): 'csv' | 'parquet' | undefined {
  return asOneOf(value, FILE_FORMATS);
}

/**
 * Narrow an untyped stored `strategy` to the supported set, else `undefined` — same reasoning as
 * `asFileFormat`: the suite target is an untyped JSONB bag.
 */
export function asBatchStrategy(value: unknown): 'latest' | 'specific' | undefined {
  return asOneOf(value, BATCH_STRATEGIES);
}

const FILE_FORMATS = ['csv', 'parquet'] as const;
const BATCH_STRATEGIES = ['latest', 'specific'] as const;

export interface AssembledTarget {
  /** The target to send: `null` = leave targetless (no field was filled). */
  target: RunTarget | null;
  /** Set when the section was started but a required field is missing. */
  error?: { field: keyof TargetFormValues; message: string };
}

const trimmed = (v?: string): string | undefined => {
  const t = v?.trim();
  return t ? t : undefined;
};

/** Light "does this pattern look like it has a capture group" heuristic — NOT a full regex parse. */
export function hasCaptureGroup(pattern: string): boolean {
  const withoutEscapedParens = pattern.replace(/\\[()]/g, '');
  return /\((?!\?(?:[:=!]|<[=!]))/.test(withoutEscapedParens);
}

/**
 * Assemble a flat-file *batch* target (#1180): `target_pattern` is required, `target_strategy`
 * defaults to `latest` (mirroring the backend's own `target.get("strategy", "latest")`).
 */
function assembleBatchTarget(v: TargetFormValues): AssembledTarget {
  const prefix = trimmed(v.target_prefix);
  const pattern = trimmed(v.target_pattern);
  const strategy = v.target_strategy ?? 'latest';
  const batch = trimmed(v.target_batch);
  // An explicit non-default strategy pick counts as "the section was started" too, not just a
  // filled prefix/pattern/batch.
  if (!prefix && !pattern && !batch && strategy === 'latest') return { target: null };
  if (!pattern) {
    return {
      target: null,
      error: { field: 'target_pattern', message: 'Pattern is required to run this suite.' },
    };
  }
  if (strategy === 'specific') {
    if (!batch) {
      return {
        target: null,
        error: {
          field: 'target_batch',
          message: "Strategy 'specific' requires a batch key to select.",
        },
      };
    }
    if (!hasCaptureGroup(pattern)) {
      return {
        target: null,
        error: {
          field: 'target_pattern',
          message:
            "Strategy 'specific' needs a capture group in the pattern to extract the batch " +
            'key, e.g. `orders_([a-z_]+)\\.csv`.',
        },
      };
    }
  }
  return {
    target: {
      pattern,
      strategy,
                extra="Scopes the object listing, e.g. a container/folder path."
              >
                <Input placeholder="adls_flatfile/logistics_tracking/" />
              </Form.Item>
              <Form.Item
                name="target_pattern"
                label="Filename pattern (regex)"
                extra="The first capture group is the batch key — required for the 'specific' strategy."
              >
                <Input placeholder="tracking_events_([a-z_]+)\.csv" />
              </Form.Item>
              <Form.Item name="target_strategy" label="Strategy" initialValue="latest">
                <Select
                  options={[
                    { value: 'latest', label: 'Latest (greatest batch key)' },
                    { value: 'specific', label: 'Specific batch key' },
                  ]}
                />
              </Form.Item>
              {strategy === 'specific' && (
                <Form.Item
                  name="target_batch"
                  label="Batch key"
                  extra="The exact value the pattern's capture group must match."
                >
                  <Input placeholder="ready" />
                </Form.Item>
              )}
              <BatchPreviewHint suiteId={suiteId} />
            </>
          ) : (
            <>
              {connection && (
                <FileBrowserButton
                  connectionId={connection.id}
                  rootLabel={rootLabel}
                  mode="file"
                  onPick={(path) => form.setFieldsValue({ target_path: path })}
                />
              )}
              <Form.Item name="target_path" label="File path">
                <Input placeholder="container/path/to/data.csv" />
              </Form.Item>
              <Form.Item name="target_format" label="File format">
                <Select
                  allowClear
                  placeholder="Infer from extension"
                  options={[
                    { value: 'csv', label: 'CSV' },
                    { value: 'parquet', label: 'Parquet' },
                  ]}
                />
              </Form.Item>
            </>
          )}
        </>
      ) : kind === 'iceberg' ? (
        <>
          {/* Iceberg addresses a table by `namespace.table` (no SQL schema). Put the
              namespace in its own field — don't also dot-qualify Table, or the two
              fold to `namespace.namespace.table`. */}

            "no active warehouse",
            "unknown database",
            "unknown schema",
            "unknown table",
            "invalid identifier",
            # SQL Server's Msg 208 — a table, view or schema that does not exist.
            "invalid object name",
            "missing",
            "keyerror",
        ),
    ),
)


def classify_failure_category(exc: BaseException) -> FailureCategory:
    """Best-effort category for a run/dry-run failure. Never raises."""
    haystack = f"{type(exc).__name__}: {exc}".lower()
    for category, markers in _MARKERS:
        if any(marker in haystack for marker in markers):
            return category
    return FailureCategory.UNKNOWN


def classify_failure_reason(exc: BaseException) -> str:
    """The fixed, secret-free user-facing reason for a failed run/dry-run (#605)."""
    return _MESSAGES[classify_failure_category(exc)]


def safe_failure_reason(exc: BaseException) -> str:
    """The user-facing reason: verbatim when SAFE-marked, classified otherwise."""
    if isinstance(exc, SafeMonitorError) and str(exc):
        return str(exc)
    return classify_failure_reason(exc)


# ── Orchestration-poll classification (#1285) ──────────────────────────────── Same shape as the
# inventory-sync case below.
_ORCHESTRATION_MESSAGES: dict[FailureCategory, str] = {
    FailureCategory.CONFIG: (
        "DataQ could not get what it asked for from this orchestration provider — the "
        "pipeline/DAG, or the artifact it publishes, may no longer exist, or the "
        "connection may point somewhere that no longer holds it. Check the connection's "
        "settings and the pipeline/DAG id on its trigger bindings."
    ),
    FailureCategory.CONNECTIVITY: (
        "The orchestration provider could not be reached (network, DNS, TLS, a timeout, "
        "or the host or storage it lives on is down). Check that it is running and "
        "reachable from DataQ."
    ),
    FailureCategory.PERMISSION: (
        "The orchestration provider rejected the credentials, or the identity is missing a "
        "permission it needs to read runs. Re-check the connection's credentials and its "
        "access to the pipelines/DAGs."
    ),
    FailureCategory.UNKNOWN: (
        "Polling this orchestration connection failed for a reason DataQ could not "
        "classify. Re-test the connection, and check the worker logs for the underlying "
        "error."
    ),
}

