import io
import json

import pyarrow.json as pj

body = "".join(json.dumps({"b": i, "a": "t" * 90}) + "\n" for i in range(100_000)).encode()


class Spy(io.RawIOBase):
    def __init__(self, b):
        self.b = io.BytesIO(b)
        self.calls = []

    def readable(self):
        return True

    def seekable(self):
        return True

    def seek(self, o, w=0):
        return self.b.seek(o, w)

    def tell(self):
        return self.b.tell()

    def read(self, n=-1):
        d = self.b.read(n)
        self.calls.append((n, len(d)))
        return d

    def readinto(self, buf):
        d = self.read(len(buf))
        buf[: len(d)] = d
        return len(d)


for threads in (False, True):
    s = Spy(body)
    r = pj.open_json(s, read_options=pj.ReadOptions(block_size=1 << 20, use_threads=threads))
    print(threads, r.schema.names, s.calls[:5], len(s.calls), sum(c[1] for c in s.calls))
    r.close()
    s = Spy(body)
    r = pj.open_json(s, read_options=pj.ReadOptions(block_size=1 << 20, use_threads=threads))
    b = r.read_next_batch()
    print(" after 1 batch", b.num_rows, len(s.calls), sum(c[1] for c in s.calls))

